import{_ as o,o as t,c as e,a5 as d}from"./chunks/framework.C588jwcu.js";const _=JSON.parse('{"title":"インストール","description":"","frontmatter":{"title":"インストール","order":1},"headers":[],"relativePath":"ja/latest/konadotnet/install_konadotnet.md","filePath":"ja/latest/konadotnet/install_konadotnet.md","lastUpdated":1785683504000}'),n={name:"ja/latest/konadotnet/install_konadotnet.md"};function l(i,a,s,r,c,h){return t(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h1><h2 id="基本依存関係" tabindex="-1">基本依存関係 <a class="header-anchor" href="#基本依存関係" aria-label="Permalink to &quot;基本依存関係&quot;">​</a></h2><ol><li>Konado プラグインをインストールします（必須）</li><li>C# をサポートする Godot バージョン（Godot 4.7.1 以降を推奨）</li><li>プロジェクトを Godot .NET エディターで開いてください。通常版の Godot エディターでは C# アドオンスクリプトをコンパイルまたは読み込みできません。</li></ol><h2 id="インストール手順" tabindex="-1">インストール手順 <a class="header-anchor" href="#インストール手順" aria-label="Permalink to &quot;インストール手順&quot;">​</a></h2><ol><li>konadotnet プラグインを Godot プロジェクトの <code>addons</code> ディレクトリへ展開します</li><li><code>addons/konado</code> のメインプラグインも存在することを確認します</li><li>Godot エディターで <code>Project -&gt; Project Settings -&gt; Plugins</code> を開き、先に <code>Konado</code> を有効化します</li><li>C# プロジェクトをビルドし、MSBuild エラーがないことを確認します</li><li><code>Konadotnet</code> プラグインを有効化します</li><li>プロジェクトを開き直し、自動読み込みノードと C# スクリプト状態を更新します</li></ol><h2 id="初回有効化時のよくあるエラー" tabindex="-1">初回有効化時のよくあるエラー <a class="header-anchor" href="#初回有効化時のよくあるエラー" aria-label="Permalink to &quot;初回有効化時のよくあるエラー&quot;">​</a></h2><p>C# プロジェクトをまだビルドしていない場合、初回有効化時に次のエラーが出ることがあります。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Unable to load addon script from path: &#39;res://addons/konadotnet/Konadotnet.cs&#39;.</span></span></code></pre></div><p>Godot .NET エディターでプロジェクトをビルドし、開き直してから再度有効化してください。</p><h2 id="シーン要件" tabindex="-1">シーン要件 <a class="header-anchor" href="#シーン要件" aria-label="Permalink to &quot;シーン要件&quot;">​</a></h2><p><code>DialogueManagerAPI</code> には、完全な公開 API 契約を満たす <code>KND_DialogueManager</code> ノードが必要です。ノードがシーンツリーへ追加されると自動的にバインドされ、 ノード名には依存しません。</p><p>複数の会話マネージャーがある場合は手動でバインドしてください。</p>',12)])])}const u=o(n,[["render",l]]);export{_ as __pageData,u as default};
